#!/usr/bin/env python3
"""
subtitle_generator.py - Perplexity-Grade Dynamic Kinetic Subtitle Generator
Generates Advanced SubStation Alpha (.ass) and .srt subtitles with:
- Word-level active cyan highlight tags (&H00CDB820&)
- Exact 9:16 safe zone placement (Baseline Y = 1540px, MarginV = 380px)
- Strict chunking limits (max 3-4 words per display burst)
Zero external dependencies.
"""

import os
import sys
import json
import argparse

ASS_HEADER = """[Script Info]
; Script generated by Perplexity Video-Director Subtitle Engine
Title: Perplexity Kinetic Subtitles 9:16
ScriptType: v4.00+
WrapStyle: 0
ScaledBorderAndShadow: yes
YCbCr Matrix: TV.709
PlayResX: 1080
PlayResY: 1920

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: PerplexitySubtitle,Inter,44,&H009DA3AE,&H0020B8CD,&H00111418,&H80000000,-1,0,0,0,100,100,0,0,1,3.0,0.0,2,100,100,380,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
"""

def format_ass_time(sec):
    h = int(sec // 3600)
    m = int((sec % 3600) // 60)
    s = int(sec % 60)
    cs = int(round((sec - int(sec)) * 100))
    if cs == 100:
        cs = 99
    return f"{h}:{m:02d}:{s:02d}.{cs:02d}"

def format_srt_time(sec):
    h = int(sec // 3600)
    m = int((sec % 3600) // 60)
    s = int(sec % 60)
    ms = int(round((sec - int(sec)) * 1000))
    if ms >= 1000:
        ms = 999
    return f"{h:02d}:{m:02d}:{s:02d},{ms:03d}"

def compile_dynamic_ass(word_list, chunk_size=3):
    """
    Generates word-level active highlight karaoke events.
    For each word in a chunk, a sub-event renders that word in cyan (&H00CDB820)
    and surrounding words in muted slate (&H009DA3AE).
    """
    lines = []
    for i in range(0, len(word_list), chunk_size):
        chunk = word_list[i:i+chunk_size]
        if not chunk:
            continue
        
        # For each active word in this chunk
        for active_idx, target_word in enumerate(chunk):
            w_start = format_ass_time(target_word["start"])
            w_end = format_ass_time(target_word["end"])
            
            # Build string with active word highlighted in Perplexity Cyan
            text_parts = []
            for j, w in enumerate(chunk):
                raw_text = w["word"].upper()
                if j == active_idx:
                    # Glowing cyan: &H00CDB820& (BGR in ASS), warm white text: &H00F3F3EE&
                    text_parts.append(r"{\c&H00F3F3EE&\3c&H00CDB820&\b1}" + raw_text + r"{\rPerplexitySubtitle}")
                else:
                    text_parts.append(r"{\c&H009DA3AE&\3c&H00111418&\b0}" + raw_text)
            
            dialogue_text = " ".join(text_parts)
            lines.append(f"Dialogue: 0,{w_start},{w_end},PerplexitySubtitle,,0,0,0,,{dialogue_text}")

    return ASS_HEADER + "\n".join(lines) + "\n"

def compile_srt(word_list, chunk_size=4):
    """Generates standard clean SRT subtitles."""
    srt_blocks = []
    idx = 1
    for i in range(0, len(word_list), chunk_size):
        chunk = word_list[i:i+chunk_size]
        if not chunk:
            continue
        start_t = format_srt_time(chunk[0]["start"])
        end_t = format_srt_time(chunk[-1]["end"])
        text = " ".join([w["word"].upper() for w in chunk])
        srt_blocks.append(f"{idx}\n{start_t} --> {end_t}\n{text}\n")
        idx += 1
    return "\n".join(srt_blocks)

def main():
    parser = argparse.ArgumentParser(description="Perplexity Dynamic Subtitle Compiler")
    parser.add_argument("--timestamps", required=True, help="Input timestamps JSON file")
    parser.add_argument("--out-ass", default="subtitles_safe916.ass", help="Output .ass file")
    parser.add_argument("--out-srt", default=None, help="Optional output .srt file")
    parser.add_argument("--chunk-size", type=int, default=3, help="Words per burst (default: 3)")
    args = parser.parse_args()

    with open(args.timestamps, "r", encoding="utf-8") as f:
        data = json.load(f)

    words = data.get("words", []) if isinstance(data, dict) else data

    ass_content = compile_dynamic_ass(words, args.chunk_size)
    with open(args.out_ass, "w", encoding="utf-8") as f:
        f.write(ass_content)
    print(f"[SUBTITLES COMPILED] Dynamic ASS Subtitles -> {args.out_ass}")

    if args.out_srt:
        srt_content = compile_srt(words, args.chunk_size)
        with open(args.out_srt, "w", encoding="utf-8") as f:
            f.write(srt_content)
        print(f"[SUBTITLES COMPILED] Standard SRT Subtitles -> {args.out_srt}")

if __name__ == "__main__":
    main()
